/*@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@200;300;400;500;600;700;800;900;1000&display=swap');*/
body {
    text-align:right !important;
    direction: rtl;
    font-family: 'Cairo', sans-serif !important;
}
.col-xs-5 {
    float: right !important;
}
.data-field .value {
    font-weight:bold ;
}
.print-format-preview [data-fieldtype="Table"] {
    font-weight: bold !important;
    text-align: center;
}

thead, tbody, .print-format .table-bordered th {
    border: 2px solid #000;
}

.print-format-preview [data-fieldtype="Currency"] div label,
.print-format-preview [data-fieldtype="Currency"] div {
    font-weight: bold !important;
}

.print-format .table-bordered td {
    border: 1.5px solid #00000075;
}
.print-format .table-bordered {
    border: 1px solid #00000075;
}
.print-format table td .value,.table>thead:first-child>tr:first-child>th {
    color: black;
    font-size: 16px;
}
.print-format td, .print-format th {
    padding: 5px !important;
}
[document-status] {
    margin-bottom: 0mm;
}
